  }

  .fixture-title {
    margin: 0 0 var(--space-1);
    font-size: 13px;
    font-weight: 700;
  }

  .fixture-body {
    margin: 0;
    font-size: 14px;
    line-height: 1.55;
    color: var(--ink-muted);
  }

  .fixture-body + .fixture-body {
    margin-top: var(--space-1);
  }

  .fixture-body a {
    color: var(--color-accent-700);
    text-decoration: underline;
    text-underline-offset: 2px;
  }

  /* A four-column grid at 390px is a horizontal scroll the reader has to
